/**
 * Token-snap graphic — a spacing value handle that snaps between two token ticks
 * on a loop, with a readout chip. Axis/ticks use the global .m-draw; the snap
 * motion uses component-scoped `ts-*` keyframes (unique names, reduced-motion
 * guarded). Generated by a sub-agent, integrated + trimmed.
 */

const TICKS = [
  { x: 120, label: '4', token: '--space-1' },
  { x: 200, label: '8', token: '--space-2' },
  { x: 280, label: '12', token: '--space-3' },
  { x: 360, label: '16', token: '--space-4' },
  { x: 440, label: '20', token: '--space-5' },
  { x: 520, label: '24', token: '--space-6' },
];

const AXIS_Y = 160;
const TICK_H = 12;
const FROM = TICKS[3]; // 16
const TO = TICKS[4]; // 20

const STYLES = `
  @keyframes ts-snap {
    0%, 35%   { transform: translateX(${FROM.x}px); }
    40%       { transform: translateX(${TO.x - 6}px); }
    45%, 80%  { transform: translateX(${TO.x}px); }
    85%       { transform: translateX(${FROM.x + 6}px); }
    90%, 100% { transform: translateX(${FROM.x}px); }
  }
  @keyframes ts-a { 0%,44% { opacity: 1 } 45%,80% { opacity: 0 } 81%,100% { opacity: 1 } }
  @keyframes ts-b { 0%,44% { opacity: 0 } 45%,80% { opacity: 1 } 81%,100% { opacity: 0 } }
  .ts-move { animation: ts-snap 3.2s cubic-bezier(0.3, 1.4, 0.5, 1) infinite; }
  .ts-from { animation: ts-a 3.2s step-start infinite; }
  .ts-to   { animation: ts-b 3.2s step-start infinite; }
  @media (prefers-reduced-motion: reduce) {
    .ts-move { animation: none; transform: translateX(${TO.x}px); }
    .ts-from { animation: none; opacity: 0; }
    .ts-to   { animation: none; opacity: 1; }
  }
`;

export default function TokenSnap() {
  return (
    <svg
      viewBox="0 0 640 320"
      width="100%"
      height="100%"
      role="img"
      aria-label="A spacing value snapping to the nearest design token on a scale"
      preserveAspectRatio="xMidYMid meet"
      style={{ display: 'block' }}
    >
      <style>{STYLES}</style>

      <g aria-hidden="true">
        {/* axis */}
        <line x1={80} y1={AXIS_Y} x2={560} y2={AXIS_Y} stroke="var(--m-line-2)" strokeWidth={1.5} strokeLinecap="round" pathLength={1} className="m-draw" />
        <polyline points={`552,${AXIS_Y - 5} 560,${AXIS_Y} 552,${AXIS_Y + 5}`} fill="none" stroke="var(--m-line-2)" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.08s' }} />

        {/* snap-zone bracket */}
        <line x1={FROM.x} y1={AXIS_Y - 58} x2={TO.x} y2={AXIS_Y - 58} stroke="var(--m-line-2)" strokeWidth={1} strokeLinecap="round" strokeDasharray="3 3" opacity={0.5} />
        <line x1={FROM.x} y1={AXIS_Y - 62} x2={FROM.x} y2={AXIS_Y - 54} stroke="var(--m-line-2)" strokeWidth={1} opacity={0.5} />
        <line x1={TO.x} y1={AXIS_Y - 62} x2={TO.x} y2={AXIS_Y - 54} stroke="var(--m-line-2)" strokeWidth={1} opacity={0.5} />
        <text x={(FROM.x + TO.x) / 2} y={AXIS_Y - 66} fill="var(--m-fg-dim)" fontSize={9} fontFamily="var(--m-mono)" textAnchor="middle">snap zone</text>

        {/* ticks */}
        {TICKS.map((t, i) => (
          <g key={t.label}>
            <line x1={t.x} y1={AXIS_Y - TICK_H} x2={t.x} y2={AXIS_Y + TICK_H} stroke="var(--m-line-2)" strokeWidth={1.5} strokeLinecap="round" pathLength={1} className="m-draw" style={{ animationDelay: `${0.12 + i * 0.04}s` }} />
            <text x={t.x} y={AXIS_Y + TICK_H + 16} fill="var(--m-fg-dim)" fontSize={11} fontFamily="var(--m-mono)" textAnchor="middle">{t.label}</text>
            {i % 2 === 1 && (
              <text x={t.x} y={AXIS_Y - TICK_H - 10} fill="var(--m-fg-dim)" fontSize={9} fontFamily="var(--m-mono)" textAnchor="middle" opacity={0.6}>{t.token}</text>
            )}
          </g>
        ))}

        {/* active tick overlays */}
        <line x1={FROM.x} y1={AXIS_Y - TICK_H} x2={FROM.x} y2={AXIS_Y + TICK_H} stroke="var(--m-accent)" strokeWidth={2} strokeLinecap="round" className="ts-from" />
        <line x1={TO.x} y1={AXIS_Y - TICK_H} x2={TO.x} y2={AXIS_Y + TICK_H} stroke="var(--m-accent)" strokeWidth={2} strokeLinecap="round" className="ts-to" />

        {/* handle */}
        <g className="ts-move">
          <line x1={0} y1={AXIS_Y - 24} x2={0} y2={AXIS_Y} stroke="var(--m-accent)" strokeWidth={1.5} strokeLinecap="round" />
          <rect x={-7} y={AXIS_Y - 38} width={14} height={14} rx={2} fill="var(--m-accent)" />
          <circle cx={0} cy={AXIS_Y} r={4} fill="var(--m-accent)" />
        </g>

        {/* readout chip */}
        <g className="ts-move">
          <rect x={-46} y={AXIS_Y + 30} width={92} height={20} rx={3} fill="var(--m-bg-2)" stroke="var(--m-line-2)" strokeWidth={1} />
          <line x1={0} y1={AXIS_Y + 5} x2={0} y2={AXIS_Y + 30} stroke="var(--m-line-2)" strokeWidth={1} strokeDasharray="2 2" />
          <text x={0} y={AXIS_Y + 44} fill="var(--m-accent)" fontSize={11} fontFamily="var(--m-mono)" textAnchor="middle" className="ts-from">{`16px → ${FROM.token}`}</text>
          <text x={0} y={AXIS_Y + 44} fill="var(--m-accent)" fontSize={11} fontFamily="var(--m-mono)" textAnchor="middle" className="ts-to">{`20px → ${TO.token}`}</text>
        </g>
      </g>
    </svg>
  );
}
